// Список клубов Яндекс Карт (Октябрьский). Чтобы добавить клуб — добавьте строку.
const clubs = [
  { club: 'MID',            slug: 'mid',              id: '178838287044' },
  { club: 'King Gaming',    slug: 'kinggaming',       id: '242798458847' },
  { club: 'JoJo Киберзона', slug: 'jojo_kiberzona',   id: '49561370161'  },
  { club: 'Go катку',       slug: 'go_katku',         id: '96128267060'  },
  { club: 'X Gaming',       slug: 'x_gaming',         id: '9804111217'   },
  { club: 'CyberFocus',     slug: 'cyberfocus_place', id: '42964574977'  },
];
return clubs.map(c => ({ json: { club: c.club, url: `https://yandex.ru/maps/org/${c.slug}/${c.id}/reviews/?ranking=by_time` } }));

// ===== Разбор страниц отзывов Яндекс Карт → дайджест =====
const clubs = $('Список клубов').all().map(i => i.json);
const pages = $input.all();
const DAYS = 7;

// ---------- утилиты ----------
const decode = s => String(s ?? '')
  .replace(/&nbsp;|&#160;/g, ' ').replace(/&quot;|&#34;/g, '"').replace(/&#39;|&apos;/g, "'")
  .replace(/&laquo;/g, '«').replace(/&raquo;/g, '»').replace(/&ndash;/g, '–').replace(/&mdash;/g, '—')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n));
const strip = h => decode(String(h ?? '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]*>/g, ' ')).replace(/[ \t ]+/g, ' ').replace(/\s*\n\s*/g, '\n').trim();

// парный тег: от позиции открывающего тега до его закрытия (учитывает вложенность)
function balanced(html, start) {
  const m = /^<(\w+)/.exec(html.slice(start, start + 40)); if (!m) return null;
  const tag = m[1].toLowerCase(); const re = new RegExp(`<(/?)${tag}\\b[^>]*?(/?)>`, 'gi');
  re.lastIndex = start; let depth = 0, mm;
  while ((mm = re.exec(html))) {
    if (mm[1] === '/') { depth--; if (depth === 0) return html.slice(start, re.lastIndex); }
    else if (mm[2] !== '/') depth++;
  }
  return html.slice(start);
}
// все элементы, у которых в class есть токен cls
function byClass(html, cls) {
  const out = []; const re = /<(\w+)\b[^>]*?\bclass="([^"]*)"[^>]*>/gi; let m;
  while ((m = re.exec(html))) {
    if (m[2].split(/\s+/).includes(cls)) { const el = balanced(html, m.index); if (el) { out.push(el); re.lastIndex = m.index + m[0].length; } }
  }
  return out;
}
const first = (html, cls) => { const a = byClass(html, cls); return a.length ? a[0] : null; };
const meta = (html, prop) => { const m = new RegExp(`<meta[^>]+itemprop="${prop}"[^>]+content="([^"]*)"`, 'i').exec(html) || new RegExp(`<meta[^>]+content="([^"]*)"[^>]+itemprop="${prop}"`, 'i').exec(html); return m ? decode(m[1]) : null; };

const MONTHS = { 'января':0,'февраля':1,'марта':2,'апреля':3,'мая':4,'июня':5,'июля':6,'августа':7,'сентября':8,'октября':9,'ноября':10,'декабря':11 };
const today = new Date(); const T0 = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
function parseDate(raw) {                      // → число (UTC-полночь дня) или null
  if (!raw) return null; const s = String(raw).trim().toLowerCase();
  let m;
  if ((m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s))) return Date.UTC(+m[1], +m[2]-1, +m[3]);
  if ((m = /^(\d{1,2})\.(\d{1,2})\.(\d{4})/.exec(s))) return Date.UTC(+m[3], +m[2]-1, +m[1]);
  if (s.includes('сегодня')) return T0;
  if (s.includes('вчера')) return T0 - 86400000;
  if ((m = /(\d+)\s*(?:день|дня|дней)\s*назад/.exec(s))) return T0 - (+m[1]) * 86400000;
  if ((m = /(?:^|\s)(\d{1,2})\s+([а-яё]+)(?:\s+(\d{4}))?/.exec(s)) && MONTHS[m[2]] !== undefined) {
    let y = m[3] ? +m[3] : today.getUTCFullYear(); let d = Date.UTC(y, MONTHS[m[2]], +m[1]);
    if (!m[3] && d > T0 + 86400000) d = Date.UTC(y - 1, MONTHS[m[2]], +m[1]);   // «20 декабря» в январе = прошлый год
    return d;
  }
  return null;
}
const fmt = ms => { const d = new Date(ms); return `${String(d.getUTCDate()).padStart(2,'0')}.${String(d.getUTCMonth()+1).padStart(2,'0')}.${d.getUTCFullYear()}`; };

function parseReviews(html) {
  const blocks = byClass(html, 'business-review-view');
  const res = [];
  for (const b of blocks) {
    const authorEl = first(b, 'business-review-view__author-name') || first(b, 'business-review-view__author');
    const author = authorEl ? strip(authorEl) : (meta(b, 'name') || '');
    const dateRaw = meta(b, 'datePublished') || (first(b, 'business-review-view__date') ? strip(first(b, 'business-review-view__date')) : '');
    let rating = null; let m;
    if ((m = /aria-label="[^"]*?(\d(?:[.,]\d)?)\s*(?:из|Из)\s*5/.exec(b))) rating = parseFloat(m[1].replace(',', '.'));
    else if (meta(b, 'ratingValue')) rating = parseFloat(meta(b, 'ratingValue'));
    else { const full = (b.match(/business-rating-badge-view__star[^"]*_full/g) || []).length; if (full) rating = full; }
    const textEl = first(b, 'business-review-view__body-text') || first(b, 'business-review-view__body');
    const text = textEl ? strip(textEl) : '';
    res.push({ author, dateRaw, date: parseDate(dateRaw), rating, text });
  }
  return res;
}

// ---------- обработка ----------
const cutoff = T0 - DAYS * 86400000;
const perClub = [], diag = [];
let blocksTotal = 0, okPages = 0;
clubs.forEach((c, i) => {
  const j = pages[i]?.json || {};
  const html = String(j.body ?? j.data ?? ''); const code = j.statusCode ?? (html ? 200 : 0);
  const captcha = /showcaptcha|smartcaptcha|SmartCaptcha|Вы не робот|Подтвердите, что запросы отправляли вы|captcha/i.test(html.slice(0, 200000)) && !/business-review-view/.test(html);
  const all = html ? parseReviews(html) : [];
  blocksTotal += all.length; if (code === 200 && !captcha) okPages++;
  const seen = new Set();
  const fresh = all.filter(r => r.date !== null && r.date >= cutoff && r.date <= T0 + 86400000)
    .filter(r => { const k = r.author + '|' + r.date + '|' + r.text; if (seen.has(k)) return false; seen.add(k); return true; })
    .sort((a, b) => b.date - a.date);
  const undated = all.filter(r => r.date === null).length;
  perClub.push({ club: c.club, reviews: fresh });
  diag.push(`${c.club}: HTTP ${code || 'нет ответа'}, ${Math.round(html.length / 1024)} КБ${captcha ? ', КАПЧА' : ''}, блоков отзывов ${all.length}, за неделю ${fresh.length}${undated ? `, без даты ${undated}` : ''}`);
});

const total = perClub.reduce((s, c) => s + c.reviews.length, 0);
let status = 'ok', text = '';
const failed = diag.filter((d, i) => !/блоков отзывов [1-9]/.test(d) && /КАПЧА|HTTP (?!200)/.test(d));
if (blocksTotal === 0) {
  status = 'blocked';
  text = '🚨 Дайджест отзывов Яндекс Карт: не удалось получить ни одного отзыва.\n' +
    'Скорее всего Яндекс отдаёт капчу/блокирует сервер или поменял вёрстку (это НЕ значит, что отзывов нет).\n\n' + diag.join('\n') +
    '\n\nЧто проверить: открыть любую страницу клуба в браузере; если страница открывается, а тут капча — нужен прокси с российским IP в ноде «Загрузить страницу» (Options → Proxy).';
} else if (total === 0) {
  status = 'empty';
  text = `📊 Еженедельный дайджест отзывов (Яндекс Карты)\n📅 за последние ${DAYS} дней | г. Октябрьский\n\nЗа последнюю неделю новых отзывов не появилось.` +
    (failed.length ? `\n\n⚠️ Не все страницы загрузились:\n${failed.join('\n')}` : '');
}

// тон — по оценке (детерминированно, без домыслов)
const tone = r => r === null ? '➖' : r >= 4 ? '✅' : r === 3 ? '➖' : '⚠️';
const num = n => n <= 9 ? `${n}️⃣` : `${n}.`;
let digest = '';
let pos = 0, neg = 0, neu = 0, sum = 0, cnt = 0;
if (status === 'ok') {
  const L = [`📊 Еженедельный дайджест отзывов (Яндекс Карты)`, `📅 Свежие отзывы за последние ${DAYS} дней | г. Октябрьский`];
  for (const c of perClub.filter(c => c.reviews.length)) {
    L.push('', '─────────────', `🏢 Клуб: ${c.club}`, `📝 Новых отзывов: ${c.reviews.length}`);
    c.reviews.forEach((r, k) => {
      const t = tone(r.rating); if (t === '✅') pos++; else if (t === '⚠️') neg++; else neu++;
      if (r.rating !== null) { sum += r.rating; cnt++; }
      L.push('', `${num(k + 1)} 👤 ${r.author || 'Аноним'} | 📅 ${fmt(r.date)} | ⭐ ${r.rating ?? '—'}/5`);
      L.push(r.text ? `💬 "${r.text}"` : '💬 (без текста, только оценка)'); L.push(t);
    });
  }
  const none = perClub.filter(c => !c.reviews.length).map(c => c.club);
  L.push('', '─────────────', '📌 Общий итог по неделе:', `Всего новых отзывов: ${total}`, `Позитивных: ${pos} ✅`, `Негативных: ${neg} ⚠️`, `Нейтральных: ${neu} ➖`);
  if (cnt) L.push(`Средняя оценка: ${(sum / cnt).toFixed(1)} ⭐`);
  if (none.length) L.push(`Без новых отзывов: ${none.join(', ')}`);
  if (failed.length) L.push('', '⚠️ Не все страницы загрузились:', ...failed);
  digest = L.join('\n');
}
// компактные данные для ИИ (только темы и вывод)
const forAI = perClub.flatMap(c => c.reviews.map(r => ({ club: c.club, rating: r.rating, text: (r.text || '').slice(0, 400) })));
return [{ json: { status, text, digest, total, reviews: forAI, diag } }];

// Склейка дайджеста с блоком тем/вывода от ИИ и деление на сообщения ≤ 4000 символов
const base = $('Разбор отзывов').first().json;
let ai = String($input.first().json.output || '').replace(/\*\*/g, '').trim();
let full = base.digest + (ai ? '\n\n─────────────\n' + ai : '');
const LIM = 3900, parts = []; let cur = '';
for (const line of full.split('\n')) {
  if ((cur + '\n' + line).length > LIM) { parts.push(cur); cur = line; } else cur = cur ? cur + '\n' + line : line;
}
if (cur) parts.push(cur);
return parts.map(t => ({ json: { text: t } }));
